package com.stitchtrack.controller;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;@WebServlet("/logout")public class LogoutServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession x=r.getSession(false);if(x!=null)x.invalidate();s.sendRedirect(r.getContextPath()+"/login");}}
